import { createApp, ref, type App as VueApp } from 'vue';
import host from '@tencent/program-host';
import type { IProgram } from '@tencent/program-host';
import MiniMapHud from './MiniMapHud.vue';
import type { MiniMapMarker } from './MiniMap.vue';

let mapApp: VueApp | null = null;
let unsubMarkersWatch: (() => void) | null = null;

/** 标记列表（响应式，getMarkers 每帧读取最新值） */
const markers = ref<MiniMapMarker[]>([]);

/** state 中标记数据的 key（宿主 / 其他 program 可通过 host.state 写入） */
const MARKERS_STATE_KEY = 'minimap:markers';

/** 从 host.state 读取标记并同步到本地 ref */
function syncMarkersFromState(): void {
  try {
    const value = host.state.get(MARKERS_STATE_KEY);
    if (Array.isArray(value)) {
      markers.value = value as MiniMapMarker[];
    }
  } catch {
    // ignore
  }
}

const minimap: IProgram = {
  init(): void {
    // ---- 标记数据同步：初始读取 + watch 后续变更 ----
    syncMarkersFromState();
    unsubMarkersWatch = host.state.watch(MARKERS_STATE_KEY, () => syncMarkersFromState());

    // ---- 路由表 ----
    host.router.routes([
      {
        path: '/',
        component: {
          mount(root: HTMLElement): void {
            // HUD 定位：左上角悬浮，容器穿透鼠标事件（MiniMap 仅展示，不接收交互）
            root.style.cssText =
              'position:fixed;top:62px;left:14px;pointer-events:none;z-index:400;';
            mapApp = createApp(MiniMapHud, {
              // 150×150 地图圆，配 155×155 圆形垫底容器（Figma #310:1078）
              size: 150,
              range: 40,
              rotateWithCamera: true,
              // 数据源注入（host 桥接）：
              // - 玩家位置/朝向：host.sdk.character.getPosition / getYaw（SDK v4.2.0+）
              // - 相机朝向：host.sdk.character.getCameraYaw（组件内部已处理"相机看向 -Z"的 +π 偏移）
              getPlayerPosition: () => host.sdk.character.getPosition(),
              getPlayerYaw: () => host.sdk.character.getYaw(),
              getCameraYaw: () => host.sdk.character.getCameraYaw(),
              // 标记获取函数（每帧调用，优先级高于 markers prop）
              getMarkers: () => markers.value,
            });
            mapApp.mount(root);
          },
          onUnmount(): void {
            mapApp?.unmount();
            mapApp = null;
          },
        },
      },
    ]);

    // ---- exposedApi：供宿主 / 其他 program 通过 RPC 更新标记 ----
    host.registerApi({
      setMarkers: (list: MiniMapMarker[]) => {
        markers.value = Array.isArray(list) ? list : [];
      },
      addMarker: (marker: MiniMapMarker) => {
        if (marker && marker.id) markers.value = [...markers.value, marker];
      },
      removeMarker: (markerId: string) => {
        markers.value = markers.value.filter((m) => m.id !== markerId);
      },
      getMarkers: () => [...markers.value],
    });

    console.log('[minimap] 小地图已就绪 v1');
  },

  dispose(): void {
    unsubMarkersWatch?.();
    unsubMarkersWatch = null;
    mapApp?.unmount();
    mapApp = null;
    markers.value = [];
    console.log('[minimap] 小地图已卸载');
  },
};

export default minimap;
