<script lang="ts">
import { defineComponent, ref, onMounted, onUnmounted, computed, watch, type PropType } from 'vue';

/** 小地图标记类型（参考设计稿） */
export type MiniMapMarkerType =
  // 寻物玩法
  | 'treasure' // 藏物点（金色六边形）
  | 'pickup' // 普通物品拾取点（小图标）
  // 世界基础
  | 'teleport' // 传送点
  | 'npc' // NPC
  | 'shop' // 商业区
  | 'scenic' // 文旅景点
  | 'photo' // 拍照打卡点
  | 'fishing' // 钓鱼交互点
  | 'pet' // 小动物交互点
  | 'puzzle' // 解谜小玩法点
  | 'task' // 任务点
  | 'interact' // 可交互点
  | 'event' // 民俗活动景点
  | 'music' // 音乐交互点
  | 'food' // 餐饮区
  | 'rest' // 休息区
  // 副本杀玩法
  | 'investigate' // 调查点
  | 'host' // 侦探/主持人
  | 'decrypt' // 解密
  | 'talk' // 交谈
  | 'task2' // 任务
  | 'discover' // 发现
  | 'key' // 关键线索
  | 'entrance' // 副本入口
  // 其他玩家
  | 'player'
  | 'other';

export interface MiniMapMarker {
  id: string;
  position: { x: number; y: number; z: number };
  type: MiniMapMarkerType;
  /** 可选自定义颜色 */
  color?: string;
  /** 可选标签 */
  label?: string;
  /** 是否高亮闪烁（如设计稿"初次进入提示" / "圈1闪烁"） */
  highlight?: boolean;
  /** 自定义 emoji 或图标字符 */
  iconChar?: string;
  /**
   * 该寻物圈内物品是否已全部拾完。
   * 为 true 时寻物圈降级为"已拾完"灰色状态（圈不消失），且不再显示圈内拾取点。
   */
  collected?: boolean;
}

/** 玩家信息（用于显示其他玩家头像） */
export interface MiniMapPlayer {
  id: string;
  position: { x: number; y: number; z: number };
  avatar?: string; // 头像 URL 或 emoji
  name?: string;
}

// ==================== 标记类型配置 ====================

interface MarkerConfig {
  shape: 'shield' | 'hex' | 'circle' | 'none';
  bgRadius: number;
  bgColor: string;
  strokeColor: string;
  icon: string; // emoji 或文字
  iconColor?: string;
  iconSize?: number;
  /** 盾形渐变起始色（顶部） */
  gradientStart?: string;
  /** 盾形渐变结束色（底部） */
  gradientEnd?: string;
  /** 是否在盾顶绘制小星 */
  starOnTop?: boolean;
  /** 小星颜色 */
  starColor?: string;
  /**
   * 完整盾形徽章图片相对路径（包含渐变+星+图标）。
   * 设置后会拼上 assetsCdnBase 形成完整 URL，drawMarker 直接 drawImage。
   */
  iconImage?: string;
}

/**
 * 获取某类标记的渲染配置。
 * @param type    标记类型
 * @param base    资源 CDN 根地址，用于拼接 iconImage 完整 URL
 */
function getMarkerConfig(type: MiniMapMarkerType, base: string): MarkerConfig {
  const joinUrl = (p?: string) => (p && base ? `${base}/${p}` : undefined);
  const configs: Record<MiniMapMarkerType, MarkerConfig> = {
    // ==== 寻物玩法（盾形徽章风格，参考设计稿） ====
    treasure: {
      // 藏物点：金色盾形徽章图（icon_treasure.png，含渐变+星+图标）
      shape: 'shield',
      bgRadius: 10,
      bgColor: '',
      strokeColor: '#FFE082',
      gradientStart: '#E8B547',
      gradientEnd: '#7B5C1F',
      icon: '🎁',
      iconSize: 10,
      starOnTop: true,
      starColor: '#FFF8DC',
      iconImage: 'https://mogs-1300354879.cos.ap-shanghai.myqcloud.com/mogs/nobody/gs-viewer/treasure-hunt/digital_world_collection/icon_treasure.png',
    },
    pickup: {
      // 普通拾取点：深蓝盾形徽章图（icon_normal_treasure.png，含渐变+星+图标）
      shape: 'shield',
      bgRadius: 9,
      bgColor: '',
      strokeColor: '#8BB5D8',
      gradientStart: '#5A6478',
      gradientEnd: '#1F2937',
      icon: '🎒',
      iconSize: 9,
      starOnTop: true,
      starColor: '#A8D0F0',
      iconImage: 'https://mogs-1300354879.cos.ap-shanghai.myqcloud.com/mogs/nobody/gs-viewer/treasure-hunt/digital_world_collection/icon_normal_treasure.png',
    },
    // ==== 世界基础 ====
    teleport: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(40, 55, 80, 0.85)',
      strokeColor: '#5FA3CE',
      icon: '✧',
      iconColor: '#5FA3CE',
      iconSize: 11,
    },
    npc: {
      shape: 'circle',
      bgRadius: 7,
      bgColor: 'rgba(95, 163, 206, 0.9)',
      strokeColor: '#fff',
      icon: '',
      iconSize: 0,
    },
    shop: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(60, 70, 85, 0.85)',
      strokeColor: '#C9A227',
      icon: '🛍',
      iconSize: 10,
    },
    scenic: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(60, 70, 85, 0.85)',
      strokeColor: '#8FBC8F',
      icon: '⛰',
      iconSize: 10,
    },
    photo: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(60, 70, 85, 0.85)',
      strokeColor: '#9BA8B8',
      icon: '📷',
      iconSize: 9,
    },
    fishing: {
