      strokeColor: '#FFA500',
      icon: '🍴',
      iconSize: 9,
    },
    rest: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(60, 70, 85, 0.85)',
      strokeColor: '#87CEEB',
      icon: '🛏',
      iconSize: 9,
    },
    // ==== 副本杀玩法 ====
    investigate: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#5FA3CE',
      icon: '🔍',
      iconSize: 9,
    },
    host: {
      shape: 'hex',
      bgRadius: 10,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#FFD700',
      icon: '★',
      iconColor: '#FFD700',
      iconSize: 11,
    },
    decrypt: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#9370DB',
      icon: '🔐',
      iconSize: 9,
    },
    talk: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#5FA3CE',
      icon: '💬',
      iconSize: 9,
    },
    task2: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#F0C040',
      icon: '📋',
      iconSize: 9,
    },
    discover: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#5FA3CE',
      icon: '◉',
      iconColor: '#5FA3CE',
      iconSize: 11,
    },
    key: {
      shape: 'hex',
      bgRadius: 9,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#FFD700',
      icon: '🗝',
      iconSize: 9,
    },
    entrance: {
      shape: 'hex',
      bgRadius: 10,
      bgColor: 'rgba(50, 60, 75, 0.9)',
      strokeColor: '#FF6347',
      icon: '⛩',
      iconSize: 10,
    },
    // ==== 玩家 ====
    player: {
      shape: 'circle',
      bgRadius: 9,
      bgColor: '#F0C040',
      strokeColor: '#fff',
      icon: 'P',
      iconColor: '#fff',
      iconSize: 10,
    },
    other: {
      shape: 'circle',
      bgRadius: 6,
      bgColor: '#6bcbff',
      strokeColor: '#fff',
      icon: '',
      iconSize: 0,
    },
  };
  return configs[type] || configs.other;
}

export default defineComponent({
  name: 'MiniMap',
  props: {
    size: { type: Number, default: 160 },
    range: { type: Number, default: 80 },
    /** 小地图是否跟随镜头旋转：true = 镜头朝向始终朝上（地图旋转）；false = 固定北向上 */
    rotateWithCamera: { type: Boolean, default: true },
    /** 局部地图底图 URL（俯视图） */
    mapImageUrl: { type: String, default: '' },
    /** 地图图片对应的世界坐标范围（图片中心对应世界(0,0)）单位：米 */
    mapWorldSize: { type: Number, default: 200 },
    /** 标记列表（外部可选传入；不传则用内部 NPC 轮询） */
    markers: { type: Array as PropType<MiniMapMarker[]>, default: () => [] },
    /**
     * 标记获取函数（高频回调，每帧调用）
     * 优先级高于 markers prop，用于从外部数据源动态拉取标记
     */
    getMarkers: { type: Function as PropType<() => MiniMapMarker[]>, default: null },
    /** 房间内其他玩家 */
    players: { type: Array as PropType<MiniMapPlayer[]>, default: () => [] },
    /** 是否显示交互区域高亮圈（设计稿中的虚线圈） */
    showInteractionRing: { type: Boolean, default: true },
    /** 交互圈半径（世界单位） */
    interactionRingRadius: { type: Number, default: 20 },
    /** 是否高亮闪烁交互圈（初次进入游戏的玩家提示用；静态开关） */
    highlightInteractionRing: { type: Boolean, default: false },
    /**
     * 【预留接口】动态判断是否为"初次进入的玩家"（每帧调用）
     * 挂载方可通过 host 注入；返回 true 时所有交互圈金色高亮闪烁。
     * 优先级高于 highlightInteractionRing，未注入时回退到该布尔开关。
     */
    getIsFirstTimeVisit: { type: Function as PropType<() => boolean>, default: null },
    /**
     * 资源 CDN 根地址（不含末尾斜杠），用于拼接标记图标图片（如 icon_treasure.png）。
     * 不传则不加载图标图片，标记会回退到手绘 path/emoji 样式。
     */
    assetsCdnBase: { type: String, default: '' },
    /** 玩家箭头图片相对路径（相对 assetsCdnBase），默认 'icon_arrow.png'。留空则用程序绘制箭头。 */
    arrowIconPath: { type: String, default: 'icon_arrow.png' },
    // ==================== 数据源函数（由挂载方通过 host 注入） ====================
    /** 获取玩家世界坐标 */
    getPlayerPosition: {
      type: Function as PropType<() => { x: number; y: number; z: number } | null>,
      default: null,
    },
    /** 获取玩家朝向 yaw（弧度） */
    getPlayerYaw: { type: Function as PropType<() => number>, default: null },
    /** 获取相机朝向 yaw（弧度） */
    getCameraYaw: { type: Function as PropType<() => number>, default: null },
    /** 获取 NPC 列表 */
    getNPCList: {
      type: Function as PropType<() => Array<{
        id?: string;
        name?: string;
        position?: { x: number; y: number; z: number };
        isActive?: boolean;
        isCulled?: boolean;
      }>>,
      default: null,
    },
  },
  setup(props) {
    const canvasRef = ref<HTMLCanvasElement | null>(null);
    const canvasSize = computed(() => props.size * devicePixelRatio);

    const containerStyle = computed(() => ({
      width: `${props.size}px`,
      height: `${props.size}px`,
    }));

    let animFrameId = 0;
    let markerTimer: number | null = null;
    let pulsePhase = 0; // 闪烁动画相位
    const innerMarkers = ref<MiniMapMarker[]>([]);
    const mapImage = ref<HTMLImageElement | null>(null);
    const mapImageLoaded = ref(false);

    // 头像图片缓存
    const avatarCache = new Map<string, HTMLImageElement>();
    // 标记图标图片缓存（treasure/pickup 的盾形徽章图）
    const markerImageCache = new Map<string, HTMLImageElement>();

    // 玩家方向箭头图片（icon_arrow.png）
    const arrowImage = ref<HTMLImageElement | null>(null);
    const arrowImageLoaded = ref(false);

    function reloadArrowImage() {
      if (!props.assetsCdnBase || !props.arrowIconPath) {
        arrowImage.value = null;
        arrowImageLoaded.value = false;
        return;
      }
      const url = `${props.assetsCdnBase}/${props.arrowIconPath}`;
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        arrowImage.value = img;
        arrowImageLoaded.value = true;
      };
      img.onerror = () => {
        console.warn('[MiniMap] 箭头图片加载失败:', url);
      };
      img.src = url;
    }
    watch(() => [props.assetsCdnBase, props.arrowIconPath], reloadArrowImage, { immediate: true });

    // 每个标记所属寻物圈是否已被玩家进入（每帧由寻物圈聚类计算，供标点显隐使用）
    const ringInsideMap = new Map<string, boolean>();

    /** 获取当前所有标记（合并外部数据源与内部 NPC，每帧实时调用） */
    function getAllMarkers(): MiniMapMarker[] {
      // 优先使用 getMarkers 函数（实时获取最新数据）
      const externalMarkers = props.getMarkers ? props.getMarkers() : props.markers;
      return [...externalMarkers, ...innerMarkers.value];
    }

    /** 加载地图图片 */
    function loadMapImage(url: string) {
      if (!url) {
        mapImage.value = null;
        mapImageLoaded.value = false;
        return;
      }
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        mapImage.value = img;
        mapImageLoaded.value = true;
      };
      img.onerror = () => {
        console.warn('[MiniMap] 地图图片加载失败:', url);
        mapImageLoaded.value = false;
      };
      img.src = url;
    }

    watch(() => props.mapImageUrl, loadMapImage, { immediate: true });

    /** 加载头像 */
    function loadAvatar(url: string): HTMLImageElement | null {
      if (!url) return null;
      if (avatarCache.has(url)) return avatarCache.get(url)!;
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.src = url;
      avatarCache.set(url, img);
      return img;
    }

    /** 加载标记图标（盾形徽章图，未加载完返回 null，Canvas drawImage 不会崩） */
    function loadMarkerImage(url: string): HTMLImageElement | null {
      if (!url) return null;
      if (markerImageCache.has(url)) return markerImageCache.get(url)!;
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.src = url;
      markerImageCache.set(url, img);
      return img;
    }

    /** 从 props 拿玩家位置（挂载方通过 host.getPlayerPosition 注入） */
    function getPlayerPosition(): { x: number; y: number; z: number } | null {
      try {
        return props.getPlayerPosition ? props.getPlayerPosition() : null;
      } catch {
        return null;
      }
    }

    /** 从 props 拿玩家 yaw（挂载方通过 host.getPlayerYaw 注入） */
    function getPlayerYaw(): number {
      try {
        return props.getPlayerYaw ? (props.getPlayerYaw() || 0) : 0;
      } catch {
        return 0;
      }
    }

    /** 从 props 拿相机 yaw（挂载方通过 host.getCameraYaw 注入） */
    function getCameraYaw(): number {
      try {
        return props.getCameraYaw ? (props.getCameraYaw() || 0) : 0;
      } catch {
        return 0;
      }
    }

    /** 是否为"初次进入的玩家"（优先用注入函数，回退到 highlightInteractionRing 开关） */
    function isFirstTimeVisit(): boolean {
      try {
        if (props.getIsFirstTimeVisit) return !!props.getIsFirstTimeVisit();
      } catch {
        // ignore
      }
      return props.highlightInteractionRing;
    }

    /** 更新 NPC 标记（数据来源同样通过 props） */
    function updateInnerMarkers() {
      try {
        if (!props.getNPCList) return;
        const npcs = props.getNPCList() || [];
        innerMarkers.value = npcs
          .filter((n: any) => n.isActive && !n.isCulled)
          .map((n: any) => ({
            id: n.id,
            position: n.position
              ? { x: n.position.x, y: n.position.y, z: n.position.z }
              : { x: 0, y: 0, z: 0 },
            type: 'npc' as MiniMapMarkerType,
          }));
      } catch {
        // ignore
      }
    }

    /**
     * 世界坐标 → 小地图像素。
     * rot 为地图旋转角（弧度）：
     *  - 跟随镜头模式：rot = cameraYaw + π，使镜头前方始终朝向小地图上方；
     *  - 北向上模式：rot = 0，世界 +Z(北) 朝上、+X(东) 朝右，地图不旋转。
     * 注意：仅旋转标记/圈的「位置」，标记图标本身仍保持正立（由各绘制子函数不旋转 icon 保证）。
     */
    function worldToMap(
      worldX: number,
      worldZ: number,
      playerX: number,
      playerZ: number,
      rot: number,
      halfSize: number,
      scale: number,
    ): { x: number; y: number; dist: number; angle: number } {
      const dx = worldX - playerX;
      const dz = worldZ - playerZ;
      const dist = Math.sqrt(dx * dx + dz * dz);
      // 先按 rot 旋转世界相对坐标，再映射到 canvas（世界 +Z → -Y 上方）
      const cos = Math.cos(rot);
      const sin = Math.sin(rot);
      const rxWorld = dx * cos - dz * sin;
      const rzWorld = dx * sin + dz * cos;
      const rx = rxWorld * scale;
      const ry = -rzWorld * scale;
      const angle = Math.atan2(dz, dx);
      return { x: halfSize + rx, y: halfSize + ry, dist, angle };
    }

    /** 合并后的寻物圈（世界坐标） */
    type SearchRing = {
      cx: number;
      cz: number;
      radius: number;
      inside: boolean;
      collected: boolean;
      memberIds: string[];
    };

    /**
     * 将所有 treasure / pickup 标记聚合为互不相交的寻物圈。
     * 规则（参考设计稿"小地图中不展示两个重叠寻物圈"）：
     *  - 迭代合并：反复把任意两个"绘制圆相交（圆心距 < r1 + r2）"的圈合并为一个，
     *    直到所有圈两两不相交为止，从几何上保证画面里不会出现交叉的圈。
     *  - 每个聚类只画一个圈：圈心取成员质心，半径 = 质心到最远成员距离 + 基础半径 R，
     *    以保证覆盖全部成员且各自保留拾取范围。
     *  - 圈的大小随成员分布自然变化：相互靠近的物品越多，合并出的圈越大；
     *    但合并总次数不超过成员数，不存在"无限增大"。
     */
    function buildSearchRings(markers: MiniMapMarker[], px: number, pz: number): SearchRing[] {
      const base = props.interactionRingRadius;

      const pts = markers
        .filter((m) => m.type === 'treasure' || m.type === 'pickup')
        .map((m) => ({ id: m.id, x: m.position.x, z: m.position.z, collected: m.collected === true }));
      if (pts.length === 0) return [];

      type Pt = (typeof pts)[number];
      type Cluster = { members: Pt[]; cx: number; cz: number; radius: number };

      // 计算一组成员的圈心（质心）与半径（质心到最远成员距离 + 基础半径）
      const geoOf = (members: Pt[]): { cx: number; cz: number; radius: number } => {
        let sx = 0;
        let sz = 0;
        for (const p of members) {
          sx += p.x;
          sz += p.z;
        }
        const cx = sx / members.length;
        const cz = sz / members.length;
        let maxD = 0;
        for (const p of members) maxD = Math.max(maxD, Math.hypot(p.x - cx, p.z - cz));
        return { cx, cz, radius: maxD + base };
      };

      // 每个点先各成一簇
      const clusters: Cluster[] = pts.map((p) => ({ members: [p], ...geoOf([p]) }));

      // 迭代合并相交的圈，直到收敛（每次成功合并簇数 -1，最多合并 pts.length-1 次，必然终止）
      let merged = true;
      while (merged) {
        merged = false;
        for (let i = 0; i < clusters.length && !merged; i++) {
          for (let j = i + 1; j < clusters.length; j++) {
            const a = clusters[i];
            const b = clusters[j];
            const d = Math.hypot(a.cx - b.cx, a.cz - b.cz);
            // 两个绘制圆相交（含相切留一点间隙）则合并
            if (d < a.radius + b.radius) {
              const members = [...a.members, ...b.members];
              const geo = geoOf(members);
              // 先删下标较大的，避免索引错位
              clusters.splice(j, 1);
              clusters.splice(i, 1);
              clusters.push({ members, ...geo });
              merged = true;
              break;
            }
          }
        }
      }

      return clusters.map((c) => {
        const dist = Math.hypot(px - c.cx, pz - c.cz);
        return {
          cx: c.cx,
          cz: c.cz,
          radius: c.radius,
          inside: dist <= c.radius,
          collected: c.members.every((m) => m.collected),
          memberIds: c.members.map((m) => m.id),
        };
      });
    }

    /** 主绘制循环 */
    function draw() {
      const canvas = canvasRef.value;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const dpr = devicePixelRatio;
      const size = props.size;
      const halfSize = size / 2;
      const range = props.range;
      const playerPos = getPlayerPosition();
      const cameraYaw = getCameraYaw();
      const px = playerPos?.x ?? 0;
      const pz = playerPos?.z ?? 0;
      const scale = (halfSize - 8) / range;

      // 地图旋转角：跟随镜头时 = cameraYaw + π（镜头前方朝上），否则 0（北向上）
      const rot = props.rotateWithCamera ? cameraYaw + Math.PI : 0;

      pulsePhase = (pulsePhase + 0.04) % (Math.PI * 2);
      const pulseAlpha = 0.5 + 0.5 * Math.sin(pulsePhase); // 0~1

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.save();
      ctx.scale(dpr, dpr);

      // 1. 圆形裁剪
      ctx.beginPath();
      ctx.arc(halfSize, halfSize, halfSize - 2, 0, Math.PI * 2);
      ctx.clip();

      // 2. 地图背景（图片 or 程序化）
      drawMapBackground(ctx, size, halfSize, range, px, pz, rot);

      // 3. 藏物/拾取交互区域圈（寻物圈）
      //    将相互重叠的圈聚合为一个圈（避免小地图上出现重叠的多个圈）。
      //    交互状态（参考设计稿"圈的交互状态梳理"）：
      //    - 玩家不在圈内：边线为虚线，且不显示圈内普通物品拾取点
      //    - 玩家进入圈内：边线变为实线细线，并显示圈内物品拾取点
      //    - 圈内物品全部拾完（collected）：圈降级为灰色（圈内实线 / 圈外短虚线），不再显示标点
      //    - 初次进入的玩家：离玩家最近且仍有物品的圈以 C6E6FF 30%~80% 闪烁高亮做新手引导
      ringInsideMap.clear();
      if (props.showInteractionRing) {
        const firstTime = isFirstTimeVisit();
        const searchRings = buildSearchRings(getAllMarkers(), px, pz);

        // 记录每个标记所属寻物圈是否已被玩家进入（供标点显隐使用）
        for (const r of searchRings) {
          for (const id of r.memberIds) ringInsideMap.set(id, r.inside);
        }

        // 找出离玩家最近、仍有物品且玩家尚未进入的圈（用于新手引导闪烁）
        let nearest: SearchRing | null = null;
        let nearestDist = Infinity;
        for (const r of searchRings) {
          if (r.collected || r.inside) continue;
          const d = Math.hypot(px - r.cx, pz - r.cz);
          if (d < nearestDist) {
            nearestDist = d;
            nearest = r;
          }
        }

        for (const r of searchRings) {
          const proj = worldToMap(r.cx, r.cz, px, pz, rot, halfSize, scale);
          if (proj.dist - r.radius > range) continue; // 整圈都在可视范围外
          drawInteractionRing(ctx, proj.x, proj.y, r.radius * scale, {
            inside: r.inside,
            collected: r.collected,
            isNearest: r === nearest,
            firstTime,
            pulseAlpha,
          });
        }
      }

      // 4. 视野锥形（玩家镜头视角朝向）。跟随镜头时锥形固定朝上；北向上时按 cameraYaw 旋转。
      drawViewCone(ctx, halfSize, cameraYaw + Math.PI - rot);

      // 5. 标记点（先画其他玩家，再画 markers）
      // for (const player of props.players) {
      //   drawPlayerAvatar(ctx, player, px, pz, rot, halfSize, scale, range);
      // }
      for (const marker of getAllMarkers()) {
        drawMarker(ctx, marker, px, pz, rot, halfSize, scale, range, pulseAlpha);
      }

      // 6. 玩家指示器（跟随相机朝向，与视野锥形同方向）。
      // 跟随镜头时箭头恒朝上；北向上时为绝对相机朝向（cameraYaw + π）。
      drawPlayerArrow(ctx, halfSize, cameraYaw + Math.PI - rot);

      // 7. 边缘晕影
      const vig = ctx.createRadialGradient(
        halfSize,
        halfSize,
        halfSize * 0.6,
        halfSize,
        halfSize,
        halfSize,
      );
      vig.addColorStop(0, 'rgba(0,0,0,0)');
      vig.addColorStop(1, 'rgba(0,0,0,0.4)');
      ctx.fillStyle = vig;
      ctx.fillRect(0, 0, size, size);

      ctx.restore();

      // 8. 环形边框
      // ctx.beginPath();
      // ctx.arc(halfSize, halfSize, halfSize - 2, 0, Math.PI * 2);
      // ctx.strokeStyle = 'rgba(95, 163, 206, 0.3)';
      // ctx.lineWidth = 1.5;
      // ctx.stroke();
      // ctx.beginPath();
      // ctx.arc(halfSize, halfSize, halfSize - 1, 0, Math.PI * 2);
      // ctx.strokeStyle = 'rgba(95, 163, 206, 0.06)';
      // ctx.lineWidth = 3;
      // ctx.stroke();

      animFrameId = requestAnimationFrame(draw);
    }

    // ==================== 绘制子函数 ====================

    function drawMapBackground(
      ctx: CanvasRenderingContext2D,
      size: number,
      halfSize: number,
      range: number,
      px: number,
      pz: number,
      rot: number,
    ) {
      if (mapImage.value && mapImageLoaded.value) {
        // 局部地图：以玩家位置为中心截取地图区域
        const img = mapImage.value;
        const worldSize = props.mapWorldSize;
        // 地图图片像素 / 世界单位
        const pixPerWorld = Math.min(img.width, img.height) / worldSize;
        // 玩家在地图图片上的像素位置
        const imgCenterX = img.width / 2 + px * pixPerWorld;
        const imgCenterY = img.height / 2 - pz * pixPerWorld;
        // 截取尺寸（世界 range*2 米 = ? 像素）
        const cropSize = range * 2 * pixPerWorld;

        // 跟随镜头旋转时，正方形绘制区旋转后四角会露出圆内空缺，
        // 放大绘制/截取区域（√2≈1.42，取 1.5 更稳）保证整圆始终被覆盖。
        const cover = rot !== 0 ? 1.5 : 1;
        const drawSize = size * cover;
        const cropDraw = cropSize * cover;

        // 地图绕中心旋转 -rot，与 worldToMap 对标记的旋转（+rot）一致，使二者对齐
        ctx.save();
        ctx.translate(halfSize, halfSize);
        if (rot !== 0) ctx.rotate(-rot);
        ctx.drawImage(
          img,
          imgCenterX - cropDraw / 2,
          imgCenterY - cropDraw / 2,
          cropDraw,
          cropDraw,
          -drawSize / 2,
          -drawSize / 2,
          drawSize,
          drawSize,
        );
        ctx.restore();

        // 略微加暗地图，让标记更突出
        ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
        ctx.fillRect(0, 0, size, size);
      } else {
        // 程序化背景（无底图时）：同样绕中心旋转 -rot，与寻物圈/标记的旋转方向一致，
        // 避免"底图静止、圈在转"的违和感。旋转后正方形四角会露出圆外空缺，
        // 扩大绘制区（cover=1.5）保证整圆始终被覆盖。
        const cover = rot !== 0 ? 1.5 : 1;
        const drawSize = size * cover;

        ctx.save();
        ctx.translate(halfSize, halfSize);
        if (rot !== 0) ctx.rotate(-rot);

        // 整体背景
        ctx.fillStyle = '#383936';
        ctx.fillRect(-drawSize / 2, -drawSize / 2, drawSize, drawSize);

        // 道路/室内区域
        ctx.fillStyle = '#96A0A8';
        ctx.globalAlpha = 0.18;
        for (let i = 0; i < 30; i++) {
          const bx = (Math.sin(i * 7.3 + 1.5) * 0.5 + 0.5) * drawSize - drawSize / 2;
          const by = (Math.cos(i * 5.7 + 3.2) * 0.5 + 0.5) * drawSize - drawSize / 2;
          const bw = 10 + Math.sin(i * 2.1) * 6;
          const bh = 10 + Math.cos(i * 3.3) * 6;
          ctx.fillRect(bx, by, bw, bh);
        }
        ctx.globalAlpha = 1;

        ctx.restore();

        // 注：此前这里会画一组居中的"同心圆参考线"雷达装饰，但其外观与寻物圈相近，
        // 容易被误认成寻物圈，故移除，避免干扰。如需雷达网格可换用非圆形（如十字/方格）样式。
      }
    }

    /** 绘制单个寻物圈（按设计稿"圈的交互状态梳理"渲染不同状态） */
    function drawInteractionRing(
      ctx: CanvasRenderingContext2D,
      x: number,
      y: number,
      radius: number,
      opts: { inside: boolean; collected: boolean; isNearest: boolean; firstTime: boolean; pulseAlpha: number },
    ) {
      const { inside, collected, isNearest, firstTime, pulseAlpha } = opts;

      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);

      if (collected) {
        // 已拾完：圈降级为灰色（圈不消失）
        ctx.strokeStyle = 'rgba(150, 156, 164, 0.65)';
        if (inside) {
          // 玩家在圈内但已拾完：灰色实线
          ctx.setLineDash([]);
          ctx.lineWidth = 1;
        } else {
          // 玩家在圈外且已拾完：灰色 + 更短的虚线
          ctx.setLineDash([2, 4]);
          ctx.lineWidth = 1.2;
        }
      } else if (inside) {
        // 玩家进入圈内：边线变为实线细线（C6E6FF）
        ctx.setLineDash([]);
        ctx.strokeStyle = 'rgba(198, 230, 255, 0.9)';
        ctx.lineWidth = 1;
      } else if (firstTime && isNearest) {
        // 初次进入的玩家：最近的寻物圈以 C6E6FF 30%~80% 闪烁高亮做新手引导
        const a = 0.3 + 0.5 * pulseAlpha; // 0.3 ~ 0.8
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = `rgba(198, 230, 255, ${a})`;
        ctx.lineWidth = 2;
      } else {
        // 玩家不在圈内：边线为虚线
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = 'rgba(198, 230, 255, 0.5)';
        ctx.lineWidth = 1.2;
      }

      ctx.stroke();
      ctx.setLineDash([]);
    }

    function drawViewCone(ctx: CanvasRenderingContext2D, halfSize: number, coneRot: number) {
      const coneAngle = Math.PI / 2.5; // 约 72°
      const coneLen = halfSize * 0.7;
      ctx.save();
      ctx.translate(halfSize, halfSize);
      // coneRot 已由调用处算好（= cameraYaw + π - rot）：
      // 相机与角色模型不同，three.js 相机看向局部 -Z，getCameraYaw 返回相机四元数 euler.y，
      // 故相机实际朝向 = euler.y + π；再叠加地图旋转 -rot 得到锥形在小地图上的最终朝向。
      // 跟随镜头时 coneRot=0，锥形恒朝上；北向上时 coneRot=cameraYaw+π。
      ctx.rotate(coneRot);

      // 浅白色渐变视野范围（参考设计稿"玩家镜头视角朝向"）
      const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, coneLen);
      grad.addColorStop(0, 'rgba(255, 255, 255, 0.5)');
      grad.addColorStop(0.4, 'rgba(255, 255, 255, 0.25)');
      grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, coneLen, -Math.PI / 2 - coneAngle / 2, -Math.PI / 2 + coneAngle / 2);
      ctx.closePath();
      ctx.fill();

      ctx.restore();
    }

    function drawPlayerArrow(ctx: CanvasRenderingContext2D, halfSize: number, arrowRot: number) {
      ctx.save();
      ctx.translate(halfSize, halfSize);
      // arrowRot 已由调用处算好（= playerYaw - rot）：
      // SDK 中 yaw=0 时模型朝向 +Z（小地图上方），yaw=+π/2 时朝 +X（右方），canvas 顺时针为正，
      // 故与 yaw 同向旋转；再叠加地图旋转 -rot，得到箭头相对镜头的朝向。
      // 跟随镜头时若角色正对镜头前方，箭头朝上；北向上时为绝对 playerYaw。
      ctx.rotate(arrowRot);

      // 光晕
      const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 18);
      glow.addColorStop(0, 'rgba(95, 163, 206, 0.35)');
      glow.addColorStop(1, 'rgba(95, 163, 206, 0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(0, 0, 18, 0, Math.PI * 2);
      ctx.fill();

      // 箭头：优先用 icon_arrow.png 图片，未加载完时回退到程序绘制三角箭头
      if (arrowImage.value && arrowImageLoaded.value) {
        const img = arrowImage.value;
        // 箭头图片绘制尺寸（像素）
        const arrowSize = 18;
        // 图片原点默认朝上（-Y），与 yaw=0 朝 +Z（小地图上方）一致
        ctx.drawImage(img, -arrowSize / 2, -arrowSize / 2, arrowSize, arrowSize);
      } else {
        // 回退：蓝色三角箭头
        const as = 9;
        ctx.beginPath();
        ctx.moveTo(0, -as);
        ctx.lineTo(-as * 0.7, as * 0.55);
        ctx.lineTo(0, as * 0.2);
        ctx.lineTo(as * 0.7, as * 0.55);
        ctx.closePath();
        const arrowGrad = ctx.createLinearGradient(0, -as, 0, as * 0.6);
        arrowGrad.addColorStop(0, '#7BB5E0');
        arrowGrad.addColorStop(1, '#2E75A0');
        ctx.fillStyle = arrowGrad;
        ctx.fill();
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 1.2;
        ctx.stroke();
      }

      ctx.beginPath();
      ctx.arc(0, 0, 1.5, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.fill();
      ctx.restore();
    }

    function drawMarker(
      ctx: CanvasRenderingContext2D,
      marker: MiniMapMarker,
      px: number,
      pz: number,
      rot: number,
      halfSize: number,
      scale: number,
      range: number,
      pulseAlpha: number,
    ) {
      const p = worldToMap(marker.position.x, marker.position.z, px, pz, rot, halfSize, scale);
      if (p.dist > range) return;

      // 寻物圈内的普通物品/藏物标点（参考设计稿"物品标点"列）：
      //  - 仅当玩家进入该标记所属寻物圈时才显示标点（未进入时只显示圈边线/虚线）
      //  - 圈内物品已全部拾完时不再显示标点
      if (marker.type === 'pickup' || marker.type === 'treasure') {
        if (marker.collected) return;
        // 启用寻物圈时按"玩家是否进入所属圈"决定显隐；未启用寻物圈则始终显示
        if (props.showInteractionRing && !ringInsideMap.get(marker.id)) return;
      }

      // 高亮闪烁背景（脉冲光晕）
      if (marker.highlight) {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 16 + pulseAlpha * 5, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255, 215, 64, ${0.12 + pulseAlpha * 0.18})`;
        ctx.fill();
      }
      const cfg = getMarkerConfig(marker.type, props.assetsCdnBase);

      // 优先使用完整徽章图片（treasure/pickup 的盾形图，含渐变+星+图标）
      if (cfg.iconImage) {
        const img = loadMarkerImage(cfg.iconImage);
        if (img && img.complete && img.naturalWidth > 0) {
          // 按原图宽高比绘制，避免变形（原图 36×46，偏高）
          const h = cfg.bgRadius * 2.4;
          const w = h * (img.naturalWidth / img.naturalHeight);
          ctx.drawImage(img, p.x - w / 2, p.y - h / 2, w, h);
          return;
        }
        // 图片尚未加载完成：先画一个占位圆，等加载完下一帧自动替换
        ctx.beginPath();
        ctx.arc(p.x, p.y, cfg.bgRadius, 0, Math.PI * 2);
        ctx.fillStyle = cfg.bgColor || 'rgba(90, 100, 120, 0.85)';
        ctx.fill();
        return;
      }

      if (cfg.shape === 'shield') {
        // 盾形徽章（藏物点 / 普通拾取点）
        drawShield(ctx, p.x, p.y, cfg.bgRadius, cfg.gradientStart!, cfg.gradientEnd!, cfg.strokeColor);
        // 中心装饰图标
        if (cfg.icon) {
          ctx.fillStyle = cfg.iconColor || '#fff';
          ctx.font = `${cfg.iconSize || 11}px Arial`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(cfg.icon, p.x, p.y);
        }
        // 顶部装饰：闪光小星
        if (cfg.starOnTop) {
          drawStar(ctx, p.x, p.y - cfg.bgRadius * 0.55, 2, cfg.starColor || '#FFF8DC');
        }
      } else if (cfg.shape === 'hex') {
        drawHexagon(ctx, p.x, p.y, cfg.bgRadius, cfg.bgColor, cfg.strokeColor);
        if (cfg.icon) {
          ctx.fillStyle = cfg.iconColor || '#fff';
          ctx.font = `${cfg.iconSize || 10}px Arial`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(cfg.icon, p.x, p.y);
        }
      } else if (cfg.shape === 'circle') {
        ctx.beginPath();
        ctx.arc(p.x, p.y, cfg.bgRadius, 0, Math.PI * 2);
        ctx.fillStyle = cfg.bgColor;
        ctx.fill();
        if (cfg.strokeColor) {
          ctx.strokeStyle = cfg.strokeColor;
          ctx.lineWidth = 1;
          ctx.stroke();
        }
        if (cfg.icon) {
          ctx.fillStyle = cfg.iconColor || '#fff';
          ctx.font = `${cfg.iconSize || 10}px Arial`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(cfg.icon, p.x, p.y);
        }
      }
    }

    /** 绘制盾形徽章（藏物点 / 普通拾取点） */
    function drawShield(
      ctx: CanvasRenderingContext2D,
      x: number,
      y: number,
      r: number,
      gradStart: string,
      gradEnd: string,
      strokeColor: string,
    ) {
      ctx.save();
      ctx.translate(x, y);

      // 盾形路径（顶部六边形 + 底部尖角）
      ctx.beginPath();
      ctx.moveTo(0, -r);
      ctx.lineTo(r * 0.9, -r * 0.5);
      ctx.lineTo(r * 0.9, r * 0.35);
      ctx.lineTo(0, r);
      ctx.lineTo(-r * 0.9, r * 0.35);
      ctx.lineTo(-r * 0.9, -r * 0.5);
      ctx.closePath();

      // 阴影
      ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
      ctx.shadowBlur = 4;
      ctx.shadowOffsetY = 1;

      // 渐变填充
      const grad = ctx.createLinearGradient(0, -r, 0, r);
      grad.addColorStop(0, gradStart);
      grad.addColorStop(1, gradEnd);
      ctx.fillStyle = grad;
      ctx.fill();

      // 清除阴影画描边
      ctx.shadowColor = 'transparent';
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      ctx.strokeStyle = strokeColor;
      ctx.lineWidth = 1.2;
      ctx.stroke();

      // 内部高光（顶部）
      ctx.beginPath();
      ctx.moveTo(-r * 0.6, -r * 0.6);
      ctx.lineTo(0, -r * 0.85);
      ctx.lineTo(r * 0.6, -r * 0.6);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
      ctx.lineWidth = 0.8;
      ctx.stroke();

      ctx.restore();
    }

    /** 绘制小星星（盾顶装饰） */
    function drawStar(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string) {
      ctx.save();
      ctx.translate(x, y);
      ctx.beginPath();
      for (let i = 0; i < 5; i++) {
        const outerAngle = (Math.PI * 2 * i) / 5 - Math.PI / 2;
        const innerAngle = outerAngle + Math.PI / 5;
        if (i === 0) ctx.moveTo(r * Math.cos(outerAngle), r * Math.sin(outerAngle));
        else ctx.lineTo(r * Math.cos(outerAngle), r * Math.sin(outerAngle));
        ctx.lineTo(r * 0.45 * Math.cos(innerAngle), r * 0.45 * Math.sin(innerAngle));
      }
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
      ctx.restore();
    }

    function drawPlayerAvatar(
      ctx: CanvasRenderingContext2D,
      player: MiniMapPlayer,
      px: number,
      pz: number,
      rot: number,
      halfSize: number,
      scale: number,
      range: number,
    ) {
      const p = worldToMap(player.position.x, player.position.z, px, pz, rot, halfSize, scale);
      if (p.dist > range) return;

      const r = 9;
      // 圆形底色
      ctx.beginPath();
      ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
      ctx.fillStyle = '#F0C040';
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.5;
      ctx.stroke();

      // 头像图片或字母
      if (player.avatar && /^https?:/.test(player.avatar)) {
        const img = loadAvatar(player.avatar);
        if (img?.complete && img.naturalWidth > 0) {
          ctx.save();
          ctx.beginPath();
          ctx.arc(p.x, p.y, r - 1, 0, Math.PI * 2);
          ctx.clip();
          ctx.drawImage(img, p.x - r, p.y - r, r * 2, r * 2);
          ctx.restore();
        }
      } else {
        const letter = player.avatar || player.name?.[0]?.toUpperCase() || 'P';
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 10px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(letter, p.x, p.y);
      }
    }

    function drawHexagon(
      ctx: CanvasRenderingContext2D,
      x: number,
      y: number,
      r: number,
      fillColor: string,
      strokeColor: string,
    ) {
      ctx.save();
      ctx.translate(x, y);
      ctx.beginPath();
      for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 3) * i - Math.PI / 2;
        const hx = r * Math.cos(angle);
        const hy = r * Math.sin(angle);
        if (i === 0) ctx.moveTo(hx, hy);
        else ctx.lineTo(hx, hy);
      }
      ctx.closePath();
      ctx.fillStyle = fillColor;
      ctx.fill();
      if (strokeColor) {
        ctx.strokeStyle = strokeColor;
        ctx.lineWidth = 1.2;
        ctx.stroke();
      }
      ctx.restore();
    }

    onMounted(() => {
      animFrameId = requestAnimationFrame(draw);
      // markerTimer = window.setInterval(() => updateInnerMarkers(), 500);
    });

    onUnmounted(() => {
      cancelAnimationFrame(animFrameId);
      if (markerTimer !== null) {
        clearInterval(markerTimer);
        markerTimer = null;
      }
    });

    return { canvasRef, canvasSize, containerStyle };
  },
});
</script>

